export async function bootNodePod(): Promise<Nodepod | null> {
	if (nodePodInstance) return nodePodInstance;
	if (nodePodBootPromise) return nodePodBootPromise;

	nodePodBootPromise = (async () => {
		try {
			const pod = await Nodepod.boot({
				files: {},
				workdir: "/workspace",
